package com.eventpulse.handler;
import com.amazonaws.services.lambda.runtime.*;import com.amazonaws.services.lambda.runtime.events.*;import com.eventpulse.config.DynamoDbConfig;import com.eventpulse.repository.*;import com.eventpulse.service.*;import com.eventpulse.util.ResponseUtil;
public class NotificationHandler implements RequestHandler<APIGatewayV2HTTPEvent,APIGatewayV2HTTPResponse>{private final NotificationService notifications;public NotificationHandler(){var db=DynamoDbConfig.enhancedClient();var rr=new RegistrationRepository(db,DynamoDbConfig.table("REGISTRATIONS_TABLE","EventPulse-Registrations"));notifications=new NotificationService(com.eventpulse.config.SesConfig.client(),com.eventpulse.config.SesConfig.sender(),System.getenv("SES_CONFIGURATION_SET"),new NotificationRepository(db,DynamoDbConfig.table("NOTIFICATIONS_TABLE","EventPulse-Notifications")),rr,new UserRepository(db,DynamoDbConfig.table("USERS_TABLE","EventPulse-Users")));}public NotificationHandler(NotificationService n){notifications=n;}public APIGatewayV2HTTPResponse handleRequest(APIGatewayV2HTTPEvent r,Context c){try{if("GET".equals(r.getRequestContext().getHttp().getMethod())&&"/users/me/notifications".equals(r.getRawPath())){String id=EventHandler.user(r);int limit=20;try{String raw=r.getQueryStringParameters()==null?null:r.getQueryStringParameters().get("limit");if(raw!=null)limit=Integer.parseInt(raw);if(limit<1||limit>100)throw new NumberFormatException();}catch(NumberFormatException ex){return ResponseUtil.error(400,"INVALID_REQUEST","limit must be between 1 and 100");}return ResponseUtil.response(200,notifications.history(id,limit));}return ResponseUtil.error(404,"NOT_FOUND","Route not found");}catch(Exception e){return EventHandler.handleError(e);}}}
